package de.fitnesscoach.ui;

import android.os.Bundle;import android.text.InputType;import android.view.ViewGroup;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.time.LocalDate;import java.util.concurrent.*;import de.fitnesscoach.data.db.FitnessCoachDatabase;import de.fitnesscoach.data.entity.CheckInEntity;import de.fitnesscoach.data.repository.RoomFitnessCoachRepository;import de.fitnesscoach.domain.fitness.CheckInService;

public final class CheckInActivity extends AppCompatActivity {private final ExecutorService executor=Executors.newSingleThreadExecutor();private final SeekBar[] bars=new SeekBar[4];private EditText note;private final String[] labels={"Energie","Muskelermüdung","Motivation","Stress (optional)"};@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(32,32,32,32);TextView title=new TextView(this);title.setText("Tages-Check-in");title.setTextSize(24);root.addView(title);for(int i=0;i<4;i++){TextView l=new TextView(this);l.setText(labels[i]+": 3");root.addView(l);SeekBar s=new SeekBar(this);s.setMax(4);s.setProgress(2);final int idx=i;s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar x,int p,boolean f){l.setText(labels[idx]+": "+(p+1));}public void onStartTrackingTouch(SeekBar x){}public void onStopTrackingTouch(SeekBar x){}});bars[i]=s;root.addView(s);}note=new EditText(this);note.setHint("Optionale Notiz");note.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);root.addView(note,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));Button save=new Button(this);save.setText("Check-in speichern");save.setOnClickListener(v->save());root.addView(save);setContentView(root);load();}
 private void load(){executor.execute(()->{CheckInEntity c=FitnessCoachDatabase.getInstance(this).coachingDao().getCheckIn(LocalDate.now());if(c!=null)runOnUiThread(()->{set(0,c.energy);set(1,c.muscleFatigue);set(2,c.motivation);set(3,c.stress);note.setText(c.freeText==null?"":c.freeText);});});}private void set(int i,Integer v){if(v!=null)bars[i].setProgress(v-1);}
 private void save(){CheckInEntity c=new CheckInEntity();c.date=LocalDate.now();c.energy=bars[0].getProgress()+1;c.muscleFatigue=bars[1].getProgress()+1;c.motivation=bars[2].getProgress()+1;c.stress=bars[3].getProgress()+1;c.freeText=note.getText().toString().trim();executor.execute(()->{try{new CheckInService(new RoomFitnessCoachRepository(FitnessCoachDatabase.getInstance(this))).save(c);runOnUiThread(()->{Toast.makeText(this,"Check-in gespeichert",Toast.LENGTH_SHORT).show();finish();});}catch(RuntimeException e){runOnUiThread(()->Toast.makeText(this,"Check-in konnte nicht gespeichert werden. Prüfe die Eingaben.",Toast.LENGTH_LONG).show());}});}@Override protected void onDestroy(){executor.shutdownNow();super.onDestroy();}}
